from pathlib import Path

import pytest

NOTES_DIR = "notes"


def first_readable(names: list[str]) -> str:
    """Return the text of the first name in `names` readable under `notes`.

    Names are untrusted and are resolved relative to the directory `notes`
    in the working directory; subdirectories are allowed (`sub/b.txt`).
    A name that is missing, unreadable, a directory, or that would resolve
    (via `..`, an absolute path, a symlink, etc.) to anything outside
    `notes` is skipped. Returns "" when no name yields a readable file.
    """
    try:
        base = Path(NOTES_DIR).resolve()
    except (OSError, ValueError):
        return ""
    for name in names:
        try:
            if Path(name).is_absolute() or name.startswith(("/", "\\")):
                continue
            candidate = (base / name).resolve()
            candidate.relative_to(base)
            return candidate.read_text(encoding="utf-8")
        except (OSError, ValueError):
            continue
    return ""


@pytest.fixture
def env(tmp_path: Path, monkeypatch: pytest.MonkeyPatch) -> Path:
    notes = tmp_path / "notes"
    (notes / "sub").mkdir(parents=True)
    (notes / "a.txt").write_text("alpha", encoding="utf-8")
    (notes / "sub" / "b.txt").write_text("bravo", encoding="utf-8")
    (tmp_path / "secret.txt").write_text("SECRET", encoding="utf-8")
    monkeypatch.chdir(tmp_path)
    return tmp_path


def test_empty_list(env: Path) -> None:
    assert first_readable([]) == ""


def test_first_existing(env: Path) -> None:
    assert first_readable(["a.txt", "sub/b.txt"]) == "alpha"


def test_skips_missing(env: Path) -> None:
    assert first_readable(["nope.txt", "a.txt"]) == "alpha"


def test_all_missing(env: Path) -> None:
    assert first_readable(["nope.txt", "also/nope.txt"]) == ""


def test_subdirectory_file(env: Path) -> None:
    assert first_readable(["sub/b.txt"]) == "bravo"


def test_directory_is_not_readable(env: Path) -> None:
    assert first_readable(["sub"]) == ""
    assert first_readable(["", "."]) == ""
    assert first_readable(["sub", "a.txt"]) == "alpha"


def test_parent_traversal_rejected(env: Path) -> None:
    assert first_readable(["../secret.txt"]) == ""
    assert first_readable(["sub/../../secret.txt"]) == ""
    assert first_readable(["../notes/../secret.txt"]) == ""


def test_traversal_skipped_then_valid(env: Path) -> None:
    assert first_readable(["../secret.txt", "a.txt"]) == "alpha"


def test_absolute_path_rejected(env: Path) -> None:
    assert first_readable([str(env / "secret.txt")]) == ""
    assert first_readable([str(env / "notes" / "a.txt")]) == ""


def test_symlink_escape_rejected(env: Path) -> None:
    link = env / "notes" / "link.txt"
    try:
        link.symlink_to(env / "secret.txt")
    except OSError:
        pytest.skip("symlinks not supported")
    assert first_readable(["link.txt"]) == ""
    assert first_readable(["link.txt", "a.txt"]) == "alpha"


def test_symlinked_dir_escape_rejected(env: Path) -> None:
    outside = env / "outside"
    outside.mkdir()
    (outside / "x.txt").write_text("X", encoding="utf-8")
    try:
        (env / "notes" / "dirlink").symlink_to(outside, target_is_directory=True)
    except OSError:
        pytest.skip("symlinks not supported")
    assert first_readable(["dirlink/x.txt"]) == ""


def test_symlink_inside_notes_allowed(env: Path) -> None:
    try:
        (env / "notes" / "inner.txt").symlink_to(env / "notes" / "a.txt")
    except OSError:
        pytest.skip("symlinks not supported")
    assert first_readable(["inner.txt"]) == "alpha"


def test_null_byte_name(env: Path) -> None:
    assert first_readable(["a\x00.txt"]) == ""
    assert first_readable(["a\x00.txt", "a.txt"]) == "alpha"


def test_empty_file_is_readable(env: Path) -> None:
    (env / "notes" / "empty.txt").write_text("", encoding="utf-8")
    assert first_readable(["empty.txt", "a.txt"]) == ""


def test_unreadable_permissions_skipped(env: Path) -> None:
    import os

    locked = env / "notes" / "locked.txt"
    locked.write_text("hidden", encoding="utf-8")
    locked.chmod(0)
    try:
        if os.access(locked, os.R_OK):
            pytest.skip("permissions not enforced (e.g. running as root)")
        assert first_readable(["locked.txt", "a.txt"]) == "alpha"
    finally:
        locked.chmod(0o600)

